package com.bank.kda;

import java.util.logging.Logger;

// The portable Flink application logic. This is ordinary Flink code that would
// run identically on open-source Flink or the managed service.
class FlinkApplication {
    private static final Logger log = Logger.getLogger(FlinkApplication.class.getName());
    private final String name;

    FlinkApplication(String name) { this.name = name; }

    String getName() { return name; }

    // Represents the Flink job: event-time windows + keyed state fraud scoring.
    int scoreTransaction(String accountId, long amount) {
        // (In real Flink this runs inside a KeyedProcessFunction / SQL job.)
        int score = (int) Math.min(100, amount / 10000);
        log.fine(() -> "scored " + accountId + " amount=" + amount + " score=" + score);
        return score;
    }
}
