package com.bank.kda;

import java.util.logging.Logger;

// Models AWS Managed Service for Apache Flink: provisions KPUs, autoscales,
// checkpoints, and recovers — while running the user's Flink application.
class ManagedFlinkService {
    private static final Logger log = Logger.getLogger(ManagedFlinkService.class.getName());

    private final int minKpu;
    private final int maxKpu;
    private int currentKpu;
    private FlinkApplication app;
    private long lastCheckpoint = -1;
    private long processedSinceCheckpoint = 0;

    ManagedFlinkService(int minKpu, int maxKpu) {
        this.minKpu = minKpu;
        this.maxKpu = maxKpu;
        this.currentKpu = minKpu;
    }

    void deploy(FlinkApplication app) {
        this.app = app;
        log.info(() -> "deployed '" + app.getName() + "' on managed Flink, KPUs=" + currentKpu);
    }

    // Each KPU handles ~1000 records/sec; autoscale to meet the load.
    void handleLoad(long recordsPerSec) {
        int requiredKpu = (int) Math.ceil(recordsPerSec / 1000.0);
        int target = Math.max(minKpu, Math.min(maxKpu, requiredKpu));
        if (target != currentKpu) {
            int old = currentKpu;
            currentKpu = target;
            log.info(() -> "autoscale KPUs " + old + " -> " + currentKpu
                    + " for load " + recordsPerSec + " rec/s");
        }
        processedSinceCheckpoint += recordsPerSec;
    }

    // Managed automatic checkpointing to durable AWS storage.
    void autoCheckpoint(long nowMs) {
        lastCheckpoint = nowMs;
        long saved = processedSinceCheckpoint;
        processedSinceCheckpoint = 0;
        log.info(() -> "auto-checkpoint at " + nowMs + " (records since last=" + saved + ")");
    }

    // Managed failure recovery: restart from last checkpoint.
    void recoverFromFailure() {
        log.warning(() -> "application failed -> managed restart from checkpoint " + lastCheckpoint);
    }

    int getCurrentKpu() { return currentKpu; }
}
