package com.bank.kda;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class KdaDemo {
    private static final Logger log = Logger.getLogger(KdaDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Same Flink app you'd run on open-source Flink.
        FlinkApplication app = new FlinkApplication("fraud-scoring");
        ManagedFlinkService kda = new ManagedFlinkService(2, 32);
        kda.deploy(app);

        // Normal load.
        kda.handleLoad(1500);
        kda.autoCheckpoint(60000);

        // Salary-day spike -> autoscale up.
        kda.handleLoad(20000);
        kda.autoCheckpoint(120000);

        // A sample of the unchanged Flink logic running under the service.
        log.info("sample score for SAV2001: " + app.scoreTransaction("SAV2001", 900000));

        // Failure -> managed recovery from checkpoint.
        kda.recoverFromFailure();

        // Load subsides -> autoscale down.
        kda.handleLoad(3000);
        log.info("final KPUs = " + kda.getCurrentKpu());
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
